import numpy as np
import itertools

def task_func(data_list, file_name):
    if not data_list:
        with open(file_name, "w", encoding="utf-8"):
            pass
        return []

    numeric_parts = [tuple(item[1:]) for item in data_list]
    means = []
    lines = []

    for position, column in enumerate(
        itertools.zip_longest(*numeric_parts, fillvalue=np.nan),
        start=1
    ):
        values = []
        for value in column:
            try:
                if value is None:
                    values.append(np.nan)
                else:
                    values.append(float(value))
            except (TypeError, ValueError):
                values.append(np.nan)

        arr = np.asarray(values, dtype=float)
        if arr.size == 0 or np.all(np.isnan(arr)):
            mean_value = np.nan
        else:
            mean_value = np.nanmean(arr)

        means.append(float(mean_value) if not np.isnan(mean_value) else np.nan)
        lines.append(f"Position {position}: {means[-1]}")

    with open(file_name, "w", encoding="utf-8") as f:
        f.write("\n".join(lines))

    return means
